import random
import math

def run_trial(seed: int) -> dict:
    random.seed(seed)

    def tropicalize(matrix):
        n = len(matrix)
        for i in range(n):
            for j in range(n):
                if matrix[i][j] < 0:
                    matrix[i][j] = -matrix[i][j]
        return matrix

    def min_rank(matrix):
        n = len(matrix)
        rank = 0
        for i in range(n):
            found_nonzero = False
            for j in range(n):
                if matrix[j][i] != 0:
                    found_nonzero = True
                    break
            if not found_nonzero:
                continue
            rank += 1
            for j in range(n):
                if matrix[j][i] != 0:
                    for k in range(n):
                        matrix[j][k] -= matrix[i][k]
        return rank

    def tensor_product(a, b):
        n = len(a)
        result = [[0] * n for _ in range(n)]
        for i in range(n):
            for j in range(n):
                for k in range(n):
                    result[i][j] += a[i][k] * b[k][j]
        return result

    def acc0_circuit_complexity(matrix):
        n = len(matrix)
        complexity = 0
        for i in range(n):
            for j in range(n):
                if matrix[i][j] != 0:
                    complexity += 1
        return complexity

    def generate_instance(n):
        a = [[random.randint(0, 1) for _ in range(n)] for _ in range(n)]
        b = [[random.randint(0, 1) for _ in range(n)] for _ in range(n)]
        return tensor_product(a, b)

    n_values = [5, 10, 15, 20, 30, 40]
    results = []

    for n in n_values:
        instance = generate_instance(n)
        tropicalized = tropicalize(instance)
        rank = min_rank(tropicalized)
        complexity = acc0_circuit_complexity(instance)

        if rank > n**2 * math.log(n):
            return {
                "metric_name": "min_rank",
                "metric_value": rank,
                "instances_tested": 1,
                "conjecture_holds": False,
                "counterexample": f"n={n}, rank={rank} > O(n^2 log n)"
            }

        if complexity < n**2 * math.log(n):
            return {
                "metric_name": "acc0_circuit_complexity",
                "metric_value": complexity,
                "instances_tested": 1,
                "conjecture_holds": False,
                "counterexample": f"n={n}, complexity={complexity} < O(n^2 log n)"
            }

        results.append({
            "n": n,
            "rank": rank,
            "complexity": complexity
        })

    return {
        "metric_name": "min_rank",
        "metric_value": sum(result["rank"] for result in results) / len(results),
        "instances_tested": len(results),
        "conjecture_holds": all(result["rank"] <= n**2 * math.log(n) for result in results),
        "counterexample": ""
    }

if __name__ == "__main__":
